CREATE TABLE workspaces(id TEXT PRIMARY KEY,name TEXT NOT NULL,config_path TEXT NOT NULL,active_config_version INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE config_versions(id INTEGER PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),config_hash TEXT NOT NULL,config_json TEXT NOT NULL,is_valid INTEGER NOT NULL,activated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,validation_report TEXT);
CREATE TABLE source_definitions(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),source_id TEXT NOT NULL,physical_path TEXT NOT NULL,sheet_name TEXT NOT NULL,entity_type TEXT NOT NULL,namespace TEXT NOT NULL,mapping_json TEXT NOT NULL,config_version INTEGER NOT NULL REFERENCES config_versions(id));
CREATE TABLE source_state(source_definition_id TEXT PRIMARY KEY REFERENCES source_definitions(id),last_seen_size INTEGER,last_seen_mtime TEXT,last_seen_hash TEXT,last_checked_at TEXT,last_attempt_at TEXT,last_success_at TEXT,active_generation INTEGER,status TEXT NOT NULL DEFAULT 'never',last_error TEXT);
CREATE TABLE records(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),entity_type TEXT NOT NULL,namespace TEXT NOT NULL,business_key TEXT NOT NULL,source_definition_id TEXT NOT NULL REFERENCES source_definitions(id),source_sheet TEXT NOT NULL,source_row INTEGER NOT NULL,fields_json TEXT NOT NULL,raw_json TEXT NOT NULL,record_hash TEXT NOT NULL,last_import_generation INTEGER NOT NULL,active INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX record_identity ON records(workspace_id,entity_type,namespace,business_key);
CREATE INDEX records_entity ON records(workspace_id,entity_type,active,id);
CREATE INDEX records_business_key ON records(workspace_id,entity_type,active,business_key,id);
CREATE INDEX records_source ON records(source_definition_id,active,last_import_generation);
CREATE TABLE record_field_index(record_id TEXT NOT NULL REFERENCES records(id) ON DELETE CASCADE,field_name TEXT NOT NULL,text_value TEXT,numeric_value REAL,date_value TEXT,bool_value INTEGER,PRIMARY KEY(record_id,field_name));
CREATE INDEX field_text ON record_field_index(field_name,text_value,record_id);
CREATE INDEX field_number ON record_field_index(field_name,numeric_value,record_id);
CREATE INDEX field_date ON record_field_index(field_name,date_value,record_id);
CREATE VIRTUAL TABLE record_fts USING fts5(record_id UNINDEXED,field_name UNINDEXED,content,tokenize='unicode61 remove_diacritics 2');
CREATE TABLE relationship_definitions(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),definition_json TEXT NOT NULL);
CREATE TABLE record_relationships(relationship_id TEXT NOT NULL REFERENCES relationship_definitions(id) ON DELETE CASCADE,workspace_id TEXT NOT NULL,parent_record_id TEXT NOT NULL REFERENCES records(id),child_record_id TEXT NOT NULL REFERENCES records(id),PRIMARY KEY(relationship_id,parent_record_id,child_record_id));
CREATE INDEX related_parent ON record_relationships(parent_record_id,relationship_id,child_record_id);
CREATE INDEX related_child ON record_relationships(child_record_id,relationship_id);
CREATE TABLE documents(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),original_ref TEXT NOT NULL,resolved_path TEXT NOT NULL,document_type TEXT NOT NULL,size INTEGER,last_modified TEXT,last_verified_at TEXT,availability_status TEXT NOT NULL,status_detail TEXT,root_path TEXT NOT NULL,mapping_id TEXT NOT NULL);
CREATE TABLE record_documents(record_id TEXT NOT NULL REFERENCES records(id) ON DELETE CASCADE,document_id TEXT NOT NULL REFERENCES documents(id),document_mapping_id TEXT NOT NULL,PRIMARY KEY(record_id,document_id,document_mapping_id));
CREATE INDEX document_links ON record_documents(document_id);
CREATE TABLE import_runs(id INTEGER PRIMARY KEY,workspace_id TEXT NOT NULL,workbook TEXT NOT NULL,status TEXT NOT NULL,trigger TEXT NOT NULL,started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at TEXT,elapsed_ms INTEGER,rows_read INTEGER NOT NULL DEFAULT 0,rows_created INTEGER NOT NULL DEFAULT 0,rows_updated INTEGER NOT NULL DEFAULT 0,rows_deleted INTEGER NOT NULL DEFAULT 0,rows_unchanged INTEGER NOT NULL DEFAULT 0,generation INTEGER,error TEXT,stages_json TEXT NOT NULL DEFAULT '{}');
CREATE INDEX import_history ON import_runs(workspace_id,id DESC);
CREATE TABLE import_errors(id INTEGER PRIMARY KEY,import_id INTEGER REFERENCES import_runs(id),severity TEXT NOT NULL,source_id TEXT NOT NULL,sheet TEXT NOT NULL,row INTEGER NOT NULL,field TEXT,code TEXT NOT NULL,message TEXT NOT NULL);
CREATE INDEX run_errors ON import_errors(import_id);
CREATE TABLE app_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE ui_state(key TEXT PRIMARY KEY,value TEXT NOT NULL);
PRAGMA user_version=1;
